/* Diagnostic wrapper; copies inputs and observes real native update, no mutation. */
#include "../src/vehicle_update.h"
#include <stdio.h>
int capture_vehicle_update(TaxiVehicleUpdate*v,TaxiVehicleUpdateContext*c,const TaxiCommand*cmd,const TaxiTrig*t,const TaxiAngleTable*a,TaxiVehicleUpdateEffects*e){static unsigned tick;unsigned n=tick++;TaxiVehicleUpdate before=*v;TaxiVehicleUpdateContext context=*c;int rc=taxi_vehicle_update(v,c,cmd,t,a,e);if(n>=760&&n<=920){FILE*f=fopen("outputs/crazy-taxi-native/reports/bound-launch-vehicle-states.txt",n==760?"w":"a");if(!f)return -1;TaxiOrientation*o=&before.motion.orientation;TaxiOrientation*z=&v->motion.orientation;
fprintf(f,"%u",n);
int input[]={o->position.x,o->position.y,o->position.z,o->angle_18,o->angle_1a,o->heading_1c,o->heading_20,o->drift_69c,o->force_540,o->state_564,o->speed_544,o->timer_2a,o->flags_358,o->flags_28,o->phase_e6a,before.motion.steering.angle_578,before.motion.steering.phase_e6b,before.motion.steering.limit_7b0,before.motion.scale_7c8,before.motion.scale_e84,before.motion.dimension_594,before.force_53c,before.capacity_570,before.capacity_574,before.response_744,before.flags_4ac,context.orientation.delta,context.orientation.settings,context.orientation.submode,context.orientation.flag_1697,context.traction.flag_1696,context.traction.flag_262c,context.traction.flag_25d4,context.traction.state_2630,cmd->bytes[4]};
for(unsigned i=0;i<sizeof input/sizeof input[0];i++)fprintf(f," %d",input[i]);
int output[]={rc,z->position.x,z->position.y,z->position.z,z->heading_1c,z->heading_20,z->drift_69c,z->force_540,z->state_564,z->speed_544,z->timer_2a,z->flags_28,v->motion.response_57c,v->motion.displacement.x,v->motion.displacement.y,v->motion.displacement.z,v->response_744,c->traction.flag_262c,c->traction.flag_25d4,e->traction.score_requested,(int)e->traction.score_a,(int)e->traction.score_b,(int)e->traction.score_c};
for(unsigned i=0;i<sizeof output/sizeof output[0];i++)fprintf(f," %d",output[i]);fprintf(f,"\n");fclose(f);}return rc;}
